/**
 * SHUTOKO NIGHTS — one-shot repair for unstamped synthetic road overrides.
 *
 * Synthetic routes (`tatsumi_pa_entry`, `tatsumi_pa_exit`, …) are generated by
 * js/map.js at runtime, so a saved editor override for one has to say which
 * generated geometry it was drawn on top of. That stamp — `base` — is written
 * by the editor on every save now; overrides saved before it existed have none,
 * and HighwayMap falls back to its conservative "does this still reach the lot"
 * heuristic for them. That heuristic discards any edit that moved a connector's
 * terminus off the generated curve, which is exactly what reshaping a PA
 * connector does: the edit silently reverts on the next load.
 *
 * This script stamps those legacy entries with the polyline the CURRENT world
 * generates for each route, i.e. it asserts "this saved edit was authored
 * against today's geometry". Run it once, after checking that the edits it
 * lists are yours and not left over from an older lot fit — restoring an
 * override from a differently fitted deck is the failure mode the guard exists
 * to prevent. `data/editor/road-route-overrides.json.bak` holds the previous
 * file either way.
 *
 * Run from the repo root:
 *   node tools/hesi-editor/stamp-road-overrides.mjs            # report only
 *   node tools/hesi-editor/stamp-road-overrides.mjs --write    # stamp the draft
 *   node tools/hesi-editor/stamp-road-overrides.mjs --write --publish
 *                                                             # …and republish
 */
import { readFile, writeFile, copyFile, stat } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  ROAD_ROUTE_PATHS,
  applyRoadRouteOverrides,
  canonicalizeRoadRouteOverrides,
  productionRouteModuleSource,
  serializeProductionRoutes,
  serializeRoadRouteOverrides,
  validateProductionRouteDocument,
} from './src/overrides/road-route-schema.js';

const ROOT = fileURLToPath(new URL('../..', import.meta.url));
const write = process.argv.includes('--write');
const publish = process.argv.includes('--publish');
const file = (relativePath) => resolve(ROOT, relativePath);

const readJson = async (relativePath) => JSON.parse(await readFile(file(relativePath), 'utf8'));
const writeWithBackup = async (relativePath, contents) => {
  const target = file(relativePath);
  try {
    await stat(target);
    await copyFile(target, `${target}.bak`);
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  await writeFile(target, contents, 'utf8');
};

const production = validateProductionRouteDocument(await readJson(ROAD_ROUTE_PATHS.productionJson));
const overrides = canonicalizeRoadRouteOverrides(await readJson(ROAD_ROUTE_PATHS.source), {
  production, dropUnknown: true,
});

const synthetic = Object.entries(overrides.syntheticRoutes);
if (!synthetic.length) {
  console.log('No synthetic road route overrides saved — nothing to stamp.');
  process.exit(0);
}

// The map prints a warning per skipped override while it builds; collect them
// instead of interleaving them with this script's report.
const skipped = [];
const originalWarn = console.warn;
console.warn = (...args) => { skipped.push(args.join(' ')); };
const { HighwayMap } = await import(new URL('../../js/map.js', import.meta.url).href);
const map = new HighwayMap(null, { addLighting: false });
console.warn = originalWarn;

let stamped = 0;
for (const [id, entry] of synthetic) {
  const route = map.routes.get(id);
  if (!route) {
    console.log(`· ${id}: no such runtime route — left untouched (the world no longer generates it)`);
    continue;
  }
  if (entry.base) {
    const matches = map._matchesGeneratedBase(route, entry.base);
    console.log(`· ${id}: already stamped · base ${matches ? 'matches' : 'DOES NOT match'} the generated route`);
    continue;
  }
  if (!Array.isArray(route.generatedPoints)) {
    console.log(`· ${id}: runtime route exposes no generated polyline — left untouched`);
    continue;
  }
  entry.base = route.generatedPoints.map((point) => [...point]);
  stamped += 1;
  console.log(`· ${id}: stamped with the generated ${route.generatedPoints.length}-point polyline`
    + ` (saved edit keeps its ${entry.points.length} points)`);
}
map.dispose();

for (const warning of skipped) console.log(`  world load said: ${warning}`);

if (!stamped) {
  console.log('\nNothing to stamp.');
  process.exit(0);
}
if (!write) {
  console.log(`\n${stamped} override${stamped === 1 ? '' : 's'} would be stamped. Re-run with --write to apply.`);
  process.exit(0);
}

await writeWithBackup(ROAD_ROUTE_PATHS.source, serializeRoadRouteOverrides(overrides, { production }));
console.log(`\nStamped ${stamped} override${stamped === 1 ? '' : 's'} in ${ROAD_ROUTE_PATHS.source}`);

if (!publish) {
  console.log('Press Apply to Game in the editor (or re-run with --publish) to republish the production routes.');
  process.exit(0);
}
const output = applyRoadRouteOverrides(production, overrides);
const json = serializeProductionRoutes(output);
await writeWithBackup(ROAD_ROUTE_PATHS.productionModule, productionRouteModuleSource(json));
await writeWithBackup(ROAD_ROUTE_PATHS.productionJson, json);
console.log(`Published ${ROAD_ROUTE_PATHS.productionJson} + ${ROAD_ROUTE_PATHS.productionModule}`);
